fn first_positive(v: &Vec[Int]) -> Option[Int] {
  var i = 0;
  while i < v.len() {
    if v[i] > 0 {
      return Some(v[i]);
    }
    i = i + 1;
  }
  return None;
}

fn describe(opt: Option[Int]) -> Str {
  match opt {
    Some(n) => { return "Value: " + n; }
    None => { return "Nothing"; }
  }
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(-5);
  v.push(0);
  v.push(3);
  v.push(-1);
  let result = first_positive(&v);
  return 0;
}
